//! Actions-only original physical FD Info read lifecycle. Same scope, pending
//! ID, fixed standard-stack deadlines and last-holder native budgets as Text.
use super::*;
use n::im_content::ImContent;
fn receive_query()->Arc<ImQuery>{Arc::new(ImQuery::receive(ImBox::parse(b"P2P/1_2").unwrap(),7,1).unwrap())}
fn info_result()->Vec<u8>{let mut w=Writer::new();w.boolean(true).unwrap();w.u32(1).unwrap();w.i64(7).unwrap();w.i64(7).unwrap();w.bytes(b"private-native-sender").unwrap();w.bytes(b"Info.IO").unwrap();w.bytes(br#"{"content":"private Info IO","OnlineMsg":"not-a-grant"}"#).unwrap();w.properties(&[]).unwrap();w.properties(&[]).unwrap();w.bytes(b"").unwrap();w.finish().expose_to_transport().to_vec()}
async fn info_auth(handle:&RuntimeHandle,events:&mut mpsc::Receiver<RuntimeEvent>,owner:&AttemptOwner,scope:&RpcConnectionScope){let mut c=config(true);c.im_messages.as_mut().unwrap().receive_info=true;let setup=NativeReceiverSetup::capture(NativeReceiverPolicy::capture(&c).unwrap(),true,None).unwrap();let commands=handle.command_handle();commands.arm_native_receivers(owner,scope,setup).await.unwrap();authenticated(handle,events,owner,scope).await;commands.configure_native_receivers(owner,scope,7).await.unwrap();}
fn info_enqueue(handle:&RuntimeHandle,owner:&AttemptOwner,scope:&RpcConnectionScope,gate:Arc<ImReceiptGate>,interest:Arc<ImReadInterest>)->(oneshot::Receiver<Result<RuntimeReceipt,RuntimeError>>,oneshot::Receiver<Result<OwnedImReply,RuntimeError>>){let(reply,data)=oneshot::channel();let receipt=handle.command_handle().enqueue(owner,scope,Operation::ImRead(Box::new(ImReadWork{query:receive_query(),gate,interest,reply}))).unwrap();(receipt,data)}
#[tokio::test]
async fn info_actor_retained_original_result_stays_charged_through_logout_until_last_holder(){Box::pin(async{
    let cert=Certificates::generate("IP:127.0.0.1");let listener=TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,0)).await.unwrap();let p=router_policy(&cert.root,listener.local_addr().unwrap().port());let server=cert.server_config(&TLS13);
    let serving=tokio::spawn(async move{bounded(async move{let mut peer=CommonPeer::open(listener,server).await;peer_login(&mut peer).await;let packet=peer.next().await.unwrap();let id=query(&packet,n::im_data::RECV_METHOD);peer.send(&[reply(id,&info_result())]).await;peer_logout(&mut peer).await;}).await});
    let owner=owner();let conn=connected(&p,owner.clone(),Instant::now()+Duration::from_secs(6)).await;let scope=conn.connection_scope();let(mut handle,mut events)=conn.attach().unwrap();info_auth(&handle,&mut events,&owner,&scope).await;assert_eq!(scope.native_rpc_resources(),(0,0));
    let data=bounded(handle.command_handle().read_im(&owner,&scope,receive_query(),ImReceiptGate::fresh())).await.unwrap();assert!(data.matches(&owner,&scope));
    {let ImReplyData::Receive(value)=data.result().unwrap()else{panic!("original recv DATA")};assert_eq!(value.messages.len(),1);let content=ImContent::capture(data.request().binding(),&value.messages[0]).unwrap().unwrap();assert_eq!(content.body_kind(),"info");assert_eq!(content.info_type(),Some(b"IO".as_slice()));assert_eq!(content.value(),"private Info IO");assert_eq!(format!("{content:?}"),"ImContent(<redacted>)");}
    let retained=Arc::new(data);let last=retained.clone();let resources=scope.native_rpc_resources();assert_eq!(resources.0,1);assert!(resources.1>0);assert!(events.try_recv().is_err());
    assert!(bounded(handle.logout(&owner,&scope,&[])).await.unwrap().io_released());bounded(serving).await.unwrap();assert_eq!(scope.native_rpc_resources(),resources);drop(retained);assert_eq!(scope.native_rpc_resources(),resources);drop(last);assert_eq!(scope.native_rpc_resources(),(0,0));
}).await;}
#[tokio::test]
async fn info_actor_fully_submitted_read_cancel_ignores_late_info_and_preserves_sdk_logout(){Box::pin(async{
    let cert=Certificates::generate("IP:127.0.0.1");let listener=TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,0)).await.unwrap();let p=router_policy(&cert.root,listener.local_addr().unwrap().port());let server=cert.server_config(&TLS13);let(go,wait)=oneshot::channel();
    let serving=tokio::spawn(async move{bounded(async move{let mut peer=CommonPeer::open(listener,server).await;peer_login(&mut peer).await;let packet=peer.next().await.unwrap();let id=query(&packet,n::im_data::RECV_METHOD);wait.await.unwrap();peer.send(&[reply(id,&info_result())]).await;peer_logout(&mut peer).await;}).await});
    let owner=owner();let conn=connected(&p,owner.clone(),Instant::now()+Duration::from_secs(6)).await;let scope=conn.connection_scope();let(mut handle,mut events)=conn.attach().unwrap();info_auth(&handle,&mut events,&owner,&scope).await;let interest=ImReadInterest::original(&scope);let(receipt,data)=info_enqueue(&handle,&owner,&scope,ImReceiptGate::fresh(),interest.clone());
    assert!(bounded(receipt).await.unwrap().unwrap().matches(&owner,&scope));assert!(!interest.is_writing());interest.cancel();go.send(()).unwrap();assert_eq!(bounded(data).await.unwrap().err(),Some(RuntimeError::Cancelled));assert!(scope.is_open());assert!(events.try_recv().is_err());assert!(bounded(handle.logout(&owner,&scope,&[])).await.unwrap().io_released());bounded(serving).await.unwrap();assert_eq!(scope.native_rpc_resources(),(0,0));
}).await;}
#[tokio::test]
async fn info_actor_partial_read_cancel_closes_same_fd_and_consumes_owned_join_without_replay(){Box::pin(async{
    let cert=Certificates::generate("IP:127.0.0.1");let listener=TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,0)).await.unwrap();let p=router_policy(&cert.root,listener.local_addr().unwrap().port());let server=cert.server_config(&TLS13);
    let serving=tokio::spawn(async move{bounded(async move{let mut peer=CommonPeer::open(listener,server).await;peer_login(&mut peer).await;assert!(peer.next().await.is_none(),"no paused Info READ bytes or new query escapes");}).await});
    let owner=owner();let mut conn=connected(&p,owner.clone(),Instant::now()+Duration::from_secs(6)).await;let blocked=Arc::new(AtomicBool::new(false));let pauses=n::common_runtime::tests::gate_im_read_write(conn.common.as_mut().unwrap(),blocked.clone());let scope=conn.connection_scope();let(mut handle,mut events)=conn.attach().unwrap();info_auth(&handle,&mut events,&owner,&scope).await;blocked.store(true,Ordering::SeqCst);
    let gate=ImReceiptGate::fresh();let interest=ImReadInterest::original(&scope);let(mut receipt,data)=info_enqueue(&handle,&owner,&scope,gate.clone(),interest.clone());assert!(tokio::time::timeout(Duration::from_millis(35),&mut receipt).await.is_err());assert!(interest.is_writing());assert!(pauses.load(Ordering::SeqCst)>0);gate.retire();
    bounded(scope.closed()).await;let joined=bounded(handle.close()).await;assert!(joined.io_released());assert_eq!(joined.reason,RuntimeError::Cancelled);bounded(serving).await.unwrap();drop(receipt);drop(data);assert_eq!(scope.native_rpc_resources(),(0,0));
}).await;}
#[tokio::test]
async fn info_actor_queued_retirement_allocates_no_read_id_and_keeps_original_logout_healthy(){Box::pin(async{
    let cert=Certificates::generate("IP:127.0.0.1");let listener=TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,0)).await.unwrap();let p=router_policy(&cert.root,listener.local_addr().unwrap().port());let server=cert.server_config(&TLS13);
    let serving=tokio::spawn(async move{bounded(async move{let mut peer=CommonPeer::open(listener,server).await;peer_login(&mut peer).await;let packet=peer.next().await.unwrap();let r=decode_request(&packet[1..]).unwrap();assert_eq!(r.method,n::rpc_logout::LOGOUT_SESSION_METHOD.as_bytes());assert_eq!(r.call_id,2,"retired queued read allocated no native ID");peer.send(&[reply(r.call_id,&[0,1,0,0,0,0])]).await;assert!(peer.next().await.is_none());}).await});
    let owner=owner();let conn=connected(&p,owner.clone(),Instant::now()+Duration::from_secs(6)).await;let scope=conn.connection_scope();let(mut handle,mut events)=conn.attach().unwrap();info_auth(&handle,&mut events,&owner,&scope).await;let gate=ImReceiptGate::fresh();gate.retire();let interest=ImReadInterest::original(&scope);let(receipt,data)=info_enqueue(&handle,&owner,&scope,gate,interest.clone());
    assert_eq!(bounded(receipt).await.unwrap().err(),Some(RuntimeError::Cancelled));assert_eq!(bounded(data).await.unwrap().err(),Some(RuntimeError::Cancelled));assert!(interest.is_retired());assert!(scope.is_open());assert_eq!(scope.native_rpc_resources(),(0,0));assert!(bounded(handle.logout(&owner,&scope,&[])).await.unwrap().io_released());bounded(serving).await.unwrap();
}).await;}
#[tokio::test]
async fn info_actor_original_timeout_retires_read_only_and_late_invalid_info_does_not_break_join(){Box::pin(async{
    let cert=Certificates::generate("IP:127.0.0.1");let listener=TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,0)).await.unwrap();let p=router_policy(&cert.root,listener.local_addr().unwrap().port());let server=cert.server_config(&TLS13);let(go,wait)=oneshot::channel();
    let serving=tokio::spawn(async move{bounded(async move{let mut peer=CommonPeer::open(listener,server).await;peer_login(&mut peer).await;let packet=peer.next().await.unwrap();let id=query(&packet,n::im_data::RECV_METHOD);wait.await.unwrap();peer.send(&[reply(id,&[0])]).await;peer_logout(&mut peer).await;}).await});
    let owner=owner();let conn=connected(&p,owner.clone(),Instant::now()+Duration::from_secs(6)).await;let scope=conn.connection_scope();let(mut handle,mut events)=conn.attach().unwrap();info_auth(&handle,&mut events,&owner,&scope).await;assert_eq!(bounded(handle.command_handle().read_im(&owner,&scope,receive_query(),ImReceiptGate::fresh())).await.err(),Some(RuntimeError::Timeout));assert!(scope.is_open());assert!(events.try_recv().is_err());go.send(()).unwrap();assert!(bounded(handle.logout(&owner,&scope,&[])).await.unwrap().io_released());bounded(serving).await.unwrap();assert_eq!(scope.native_rpc_resources(),(0,0));
}).await;}
